int main() {
  std::vector<int> in{1, 2, 3, 4, 5};
  std::vector<int> r;
  r.reserve(in.size());
  for (std::size_t i = 0; i < 5; ++i)
    r[(i + 2) % 5] = in[i];  // rotate by 2
  std::cout << "size " << r.size() << ':';
  for (int x : r) std::cout << ' ' << x;
}

int main() {
  std::vector<int> in{1, 2, 3, 4, 5};
  std::vector<int> r(in.size());  // 5 zeros
  for (std::size_t i = 0; i < 5; ++i)
    r[(i + 2) % 5] = in[i];
  std::cout << "size " << r.size() << ':';
  for (int x : r) std::cout << ' ' << x;
}  // size 5: 4 5 1 2 3

int main() {
  std::vector<int> a(10);
  std::vector<int> b{10};
  std::vector<int> c(10, 5);
  std::vector<int> d{10, 5};
  std::vector<std::vector<int>> nested;
  nested.emplace_back(10);
  nested.push_back({10});
  for (auto n : {a.size(), b.size(),
      c.size(), d.size(),
      nested[0].size(), nested[1].size()})
    std::cout << n << ' ';
}

