int main() {
  std::vector<int> v{1, 2, 3, 2, 5};
  auto it =
    std::remove(v.begin(), v.end(), 2);
  std::cout << v.size() << ' '
            << (it - v.begin()) << " :";
  for (int x : v) std::cout << ' ' << x;
}

// erase-remove idiom
v.erase(std::remove(v.begin(), v.end(), 2),
        v.end());          // size 3

// C++20: one call instead
auto n = std::erase(v, 2);  // n == 2
